<?php
declare(strict_types=1);require_once __DIR__.'/includes/header.php';require_csrf();$errors=[];$username='';$email='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf())$errors[]='Your security token is invalid.';$username=trim((string)($_POST['username']??''));$email=normalize_email((string)($_POST['email']??''));$password=(string)($_POST['password']??'');$confirmation=(string)($_POST['password_confirmation']??'');if(!validate_username($username))$errors[]='Username must be 3–24 characters and use letters, numbers, dots, dashes, or underscores.';if(!validate_email($email))$errors[]='Enter a valid email address.';if(!validate_password($password))$errors[]='Password must contain an uppercase letter, lowercase letter, and number.';if($password!==$confirmation)$errors[]='Passwords do not match.';$users=load_json('users.json',[]);if($users && array_filter($users,fn($u)=>is_array($u)&&strtolower((string)($u['email']??''))===$email))$errors[]='An account with this email already exists.';if(!$errors){$user=['id'=>create_user_id(),'username'=>$username,'email'=>$email,'password_hash'=>hash_password($password),'role'=>'user','active'=>true,'created_at'=>date('c')];$users[]=$user;if(!save_json('users.json',$users))$errors[]='We could not save your account. Please try again.';else{login_user($user);header('Location: '.app_url('account.php'));exit;}}}?><main class="auth-page"><section class="auth-shell"><div class="eyebrow">Create your account</div><h1>Join 2B2X.</h1><p>Your account keeps your downloads organized and private.</p><form class="auth-form" action="<?= e(app_url('register.php')) ?>" method="post" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="field"><label for=username>Username</label><input id=username name=username autocomplete=username minlength=3 maxlength=24 required value="<?= e($username) ?>"></div><div class="field"><label for=email>Email address</label><input id=email name=email type=email autocomplete=email required value="<?= e($email) ?>"></div><div class="field"><label for=password>Password</label><div class="password-wrap"><input id=password name=password type=password autocomplete=new-password minlength=8 required><button class="password-toggle" type=button data-password-toggle>Show</button></div></div><div class="field"><label for=password_confirmation>Confirm password</label><div class="password-wrap"><input id=password_confirmation name=password_confirmation type=password autocomplete=new-password minlength=8 required><button class="password-toggle" type=button data-password-toggle>Show</button></div></div><?php if($errors):?><div class="alert error"><?= e(implode(' ',array_slice($errors,0,3))) ?></div><?php endif;?><button class="button button-primary" type=submit>Create account <span class=arrow>↗</span></button></form><div class="auth-link">Already have an account? <a href="<?= e(app_url('login.php')) ?>">Sign in</a></div></section></main><?php require_once __DIR__.'/includes/footer.php'; ?>
